<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>FollowThrough: start and sell a service business</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@600;700&family=Barlow:wght@400;500;600&display=swap" rel="stylesheet">
<style>
:root{--bg:#EEF1F4;--surface:#fff;--ink:#14233B;--muted:#4D5B70;--line:#CBD3DD;--accent:#F2B705;--accent-ink:#14233B;--bubble:#E3E8EE;--me:#14233B;--me-ink:#fff;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px);color-scheme:light}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){--bg:#0F1826;--surface:#17243A;--ink:#EDF1F6;--muted:#A5B2C4;--line:#2C3C57;--bubble:#243450;--me:#F2B705;--me-ink:#14233B;color-scheme:dark}}
:root[data-theme="dark"]{--bg:#0F1826;--surface:#17243A;--ink:#EDF1F6;--muted:#A5B2C4;--line:#2C3C57;--bubble:#243450;--me:#F2B705;--me-ink:#14233B;color-scheme:dark}
html{scroll-padding-top:env(safe-area-inset-top,0px)}*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);font:400 17px/1.6 Barlow,system-ui,sans-serif}
h1,h2,h3{font-family:"Barlow Condensed","Arial Narrow",sans-serif;font-weight:700;line-height:1.08;margin:0}
h1{font-size:clamp(2.5rem,7vw,4.4rem)}h2{font-size:clamp(1.9rem,4.5vw,2.7rem);margin-bottom:.6rem}h3{font-size:1.45rem;margin-bottom:.35rem}
p{margin:0 0 1rem;max-width:64ch}a{color:inherit}
.wrap{max-width:1080px;margin:0 auto;padding:0 22px}section{padding:56px 0}
header .wrap{display:flex;justify-content:space-between;align-items:center;gap:12px;padding-top:18px;padding-bottom:18px}
nav{display:flex;gap:18px;align-items:center;font-weight:600}nav a{text-decoration:none}
.logo{font:700 1.5rem "Barlow Condensed",sans-serif;text-decoration:none}.logo b{background:var(--accent);color:var(--accent-ink);padding:0 7px;border-radius:3px;margin-right:4px}
.btn{display:inline-block;background:var(--accent);color:var(--accent-ink);font:600 1rem Barlow,sans-serif;padding:12px 20px;border-radius:6px;text-decoration:none;border:2px solid var(--accent);cursor:pointer}
.btn.ghost{background:transparent;color:var(--ink);border-color:var(--ink)}
a:focus-visible,button:focus-visible,input:focus-visible{outline:3px solid var(--ink);outline-offset:3px}
.hero{display:grid;grid-template-columns:1.15fr 1fr;gap:40px;align-items:center}.lead{font-size:1.2rem;color:var(--muted);margin:1.1rem 0 1.5rem}
.cta{display:flex;gap:12px;flex-wrap:wrap}
.thread{background:var(--surface);border:2px solid var(--ink);border-radius:14px;padding:18px;display:flex;flex-direction:column;gap:10px}
.msg{max-width:84%;padding:10px 14px;border-radius:14px;font-size:.98rem;line-height:1.45}.them{background:var(--bubble);align-self:flex-start}.me{background:var(--me);color:var(--me-ink);align-self:flex-end}
.gap{align-self:center;color:var(--muted);font-size:.85rem;border-block:1px dashed var(--line);padding:4px 14px}
.thread .late{animation:in .5s both;animation-delay:calc(var(--i)*.7s + .6s)}@keyframes in{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.thread .late{animation:none}}
.band{background:var(--surface);border-block:1px solid var(--line)}
.cols{display:grid;grid-template-columns:repeat(3,1fr);gap:26px;margin-top:22px}.col{border-top:5px solid var(--accent);padding-top:12px}.col p{color:var(--muted);margin:0}
.cat{margin-top:28px}.cat h3{border-bottom:2px solid var(--ink);padding-bottom:6px;margin-bottom:14px}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:12px}
.tile{display:block;background:var(--surface);border:1.5px solid var(--line);border-radius:8px;padding:14px;text-decoration:none}.tile:hover{border-color:var(--ink)}
.tile b{font:700 1.3rem "Barlow Condensed",sans-serif;display:block}.tile span{color:var(--muted);font-size:.9rem}
.crumbs{font-size:.95rem;color:var(--muted);margin-bottom:10px}
.facts{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin:24px 0}
.fact{background:var(--surface);border:1.5px solid var(--line);border-radius:8px;padding:16px}.fact h3{font-size:1.15rem;color:var(--muted)}.fact p{margin:0}
.prog{font-weight:600;margin:6px 0 18px}.bar{height:8px;background:var(--line);border-radius:4px;overflow:hidden;max-width:420px}.bar i{display:block;height:100%;background:var(--accent);width:0}
.step{background:var(--surface);border:1.5px solid var(--line);border-radius:10px;padding:20px;margin-bottom:14px;display:grid;grid-template-columns:44px 1fr;gap:16px}
.step.done{border-color:var(--accent)}
.chk{width:40px;height:40px;border-radius:50%;border:2px solid var(--ink);background:transparent;color:var(--accent-ink);font-size:1.3rem;font-weight:700;cursor:pointer}
.done .chk{background:var(--accent);border-color:var(--accent)}
.tip{border-left:5px solid var(--accent);padding:2px 0 2px 14px;color:var(--muted);margin:10px 0 0}.tip b{color:var(--ink)}
.signup{background:#14233B;color:#EDF1F6;border-radius:12px;padding:28px;margin:30px 0}.signup h2,.signup p,.signup label{color:#EDF1F6}.signup a{color:#F2B705}.signup :focus-visible{outline-color:#F2B705}
.signup form{display:flex;gap:10px;flex-wrap:wrap;margin:12px 0 8px}
.signup input[type=email]{flex:1;min-width:220px;padding:12px;border-radius:6px;border:2px solid #EDF1F6;background:#fff;color:#14233B;font:inherit}
.signup label{font-size:.9rem;display:flex;gap:8px;align-items:flex-start}
.rel{display:flex;gap:10px;flex-wrap:wrap}
.demo{display:grid;grid-template-columns:190px 1fr;gap:24px;margin-top:20px}.tabs{display:flex;flex-direction:column;gap:8px}
.tabs button{font:600 1rem Barlow,sans-serif;text-align:left;padding:10px 14px;border-radius:6px;border:1.5px solid var(--line);background:var(--bg);color:var(--ink);cursor:pointer}.tabs button[aria-selected="true"]{background:var(--ink);color:var(--bg);border-color:var(--ink)}
.card{background:var(--bg);border:1.5px solid var(--line);border-radius:10px;padding:22px}.card .q{font:700 1.6rem/1.15 "Barlow Condensed",sans-serif;margin-bottom:12px}.card .a{border-left:5px solid var(--accent);padding-left:14px}
.legal h3{margin-top:22px}.legal p{color:var(--muted)}
nav{flex-wrap:wrap;justify-content:flex-end}details{background:var(--surface);border:1.5px solid var(--line);border-radius:8px;padding:12px 16px;margin-bottom:10px}summary{font-weight:600;cursor:pointer}details[open] summary{margin-bottom:8px}.tpl{background:var(--bubble);border-radius:10px;padding:12px 16px;margin:8px 0;color:var(--ink)}.legal li{color:var(--muted);margin-bottom:6px}table.cost{border-collapse:collapse;width:100%;margin:10px 0}table.cost td{border-bottom:1px solid var(--line);padding:9px 8px;vertical-align:top}table.cost td:first-child{font-weight:600;width:55%}.xs{overflow-x:auto}footer{padding:26px 0;color:var(--muted);font-size:.9rem}footer a{margin-right:14px}
@media (max-width:820px){.hero,.cols,.demo,.facts{grid-template-columns:1fr}.tabs{flex-direction:row;flex-wrap:wrap}section{padding:40px 0}nav{gap:12px}}
</style>
</head>
