var CONTACT="hello@yourdomain.com",PUBLIC="https://claude.ai/artifact/UPPHnpugi29jcunfmSrimZ",FORM_URL="/api/playbook";
var CATS=["Trades & repair","Outdoor & hauling","Cleaning & detailing"];
var STEPS=[
["Form your LLC","Register an LLC with your state (usually $50–$500) to separate personal and business liability. Use your state’s Secretary of State website."],
["Get your EIN","Apply for a free Employer Identification Number on irs.gov. It takes about 10 minutes."],
["Open a business bank account","Open business checking with your LLC papers and EIN so business money stays separate from personal money."],
["Get insurance","Buy general liability insurance before your first job. Many customers ask for proof."],
["Set your prices","Work out your costs and a profit margin, then set clear flat rates or hourly prices."],
["Find your first customers","Start with people you know, a Google Business Profile, local Facebook groups and neighbors."],
["Handle objections","Expect questions about price, timing and trust. Prepare calm, honest answers in advance."]];
var T=[
{s:"hvac",n:"HVAC",c:0,cost:"$10,000–$30,000+",season:"Summer and winter. Spring and fall are slower.",fit:"Good if you hold or can earn a license and like technical work. Most states require a license, and EPA 608 certification is required to handle refrigerants.",spend:"Licensing and exams, gauges and tools, a work van, insurance, scheduling software.",tips:["Check your state’s contractor licensing rules first. Some require the license before you register.","Free at irs.gov. Avoid sites that charge for it.","Set aside money for sales tax if your state taxes labor or parts.","Add commercial vehicle cover and ask whether you need a license bond.","Charge flat-rate prices per job and include a service call fee.","Partner with property managers and realtors for repeat work.","If a rival is cheaper, ask if their quote includes a warranty and licensed techs."]},
{s:"plumbing",n:"Plumbing",c:0,cost:"$8,000–$25,000",season:"Year-round. Winter freezes bring emergency calls.",fit:"Good if you can get licensed and handle on-call work. Many states require an apprenticeship and a license before you work alone.",spend:"License fees, hand and power tools, drain equipment, a van, insurance.",tips:["Licensing varies a lot by state, so confirm the path before spending on tools.","Free at irs.gov and takes minutes.","Keep a separate account for materials and parts to track margins.","Ask about a bond, and check what your policy excludes (water damage).","Quote flat prices for common jobs like water heaters and drains.","Landlords and property managers give steady jobs. Offer an emergency number.","When customers say “it’s just a small leak,” explain what hidden damage costs."]},
{s:"roofing",full:1,n:"Roofing",c:0,cost:"$10,000–$40,000",season:"Spring through fall. Storm seasons spike demand.",fit:"Good if you’re comfortable with heights and physical work and can handle big quotes. Insurance and workers’ comp costs are high.",spend:"Insurance and workers’ comp, ladders and safety gear, tools, a truck and trailer, material accounts.",tips:["Some states require a roofing license. Check yours before you quote.","Free at irs.gov.","Keep deposits and material costs clearly tracked. Roofing runs on cash flow.","Workers’ comp matters here. Customers often ask for proof of both policies.","Price per square (100 sq ft), add waste, tear-off and cleanup.","Door knock after storms (where legal) and ask neighbors for referrals.","When someone says “I need more quotes,” offer to explain your materials and warranty."]},
{s:"painting",n:"Painting",c:0,cost:"$2,000–$10,000",season:"Spring to fall for exteriors. Interiors work year-round.",fit:"A good low-cost start for detail-oriented people. Low barrier, but lots of competition, so reviews matter.",spend:"Sprayer, brushes and rollers, ladders, drop cloths, a vehicle, insurance.",tips:["Check if your state needs a license once jobs pass a dollar threshold.","Free at irs.gov.","Keep a record of paint and supplies to see true job profit.","Insurance protects you from damage to floors and furniture.","Price by square foot or per room, and include prep time.","Show before and after photos and ask for reviews at the end of each job.","If they say “my nephew paints,” explain prep, warranty and insurance."]},
{s:"handyman",n:"Handyman",c:0,cost:"$1,500–$8,000",season:"Year-round, with spring and fall peaks.",fit:"Great for beginners with broad skills. Many states cap job size without a license, so know your limit.",spend:"Hand and power tools, a vehicle, insurance, advertising.",tips:["Learn your state’s job-size limit. Past it, you may need a contractor license.","Free at irs.gov.","Set up invoicing so you get paid on the spot.","General liability matters more here since you work inside homes.","Set a minimum trip fee and an hourly rate, and use flat quotes for set jobs.","Post in local groups and Nextdoor, and offer small jobs to start.","When they say “that’s too much for a small job,” explain your minimum covers travel and tools."]},
{s:"landscaping",n:"Landscaping",c:1,cost:"$3,000–$15,000",season:"Spring through fall. Winter can add snow removal.",fit:"Good for people who like outdoor work. Recurring mowing clients give steady monthly income.",spend:"Mower, trimmer and blower, a trailer, a truck, insurance, fuel.",tips:["Pesticide or irrigation work may need a state license. Plain mowing usually does not.","Free at irs.gov.","Take monthly or recurring payments by card to smooth income.","Insure your equipment and get general liability.","Price per visit by lot size and set a minimum route stop fee.","Go door to door on one street so you can serve neighbors in one trip.","If they say “my kid mows for free,” point to reliability and no missed weeks."]},
{s:"junk-removal",n:"Junk Removal",c:1,cost:"$3,000–$20,000",season:"Spring cleaning and summer. Move-out seasons are busy.",fit:"Good if you can lift and want quick cash jobs. Dump fees and fuel cut margins, so pricing needs care.",spend:"Truck or trailer, dump fees, straps and dollies, insurance, advertising.",tips:["Check local rules on hauling and disposal. Some areas require permits.","Free at irs.gov.","Track dump fees per job so you know your margin.","Cover your vehicle for business use and ask about property-damage limits.","Price by truck volume (quarter, half, full) and include dump costs.","Partner with realtors, movers and property managers who need clean-outs.","If they say “I’ll just rent a dumpster,” compare the time and effort you save."]},
{s:"moving-transportation",n:"Moving & Transportation",c:1,cost:"$5,000–$40,000",season:"Summer is peak. End of month is busy.",fit:"Good if you can lift and organize crews. Local moves are simpler. Interstate moves need federal registration.",spend:"Box truck, dollies and blankets, insurance, helpers, advertising.",tips:["Local moves have state rules. Interstate moves need a USDOT number and more.","Free at irs.gov.","Keep payroll separate. Helpers may be employees, so confirm the rules.","Cargo insurance protects customer belongings and is often asked for.","Price per hour per crew with a minimum, and add travel time.","List on Google Maps and partner with realtors and apartment managers.","If they ask “can you do it cheaper?” offer a smaller crew or flexible date."]},
{s:"house-cleaning",n:"House Cleaning",c:2,cost:"$500–$5,000",season:"Year-round, with peaks before holidays and in spring.",fit:"Great low-cost start. Recurring weekly or biweekly clients build stable income, but trust is key.",spend:"Supplies, vacuum and tools, a vehicle, insurance, advertising.",tips:["Licensing is rare, but check city rules and consider a business license.","Free at irs.gov.","Take card payments and set up recurring billing for repeat clients.","Get bonded and insured. Customers trust cleaners with their homes.","Price by home size and type of clean, with a higher first-time deep clean.","Offer a first-clean discount and ask satisfied clients for referrals.","If they say “I’ll find cheaper,” highlight reliability, insurance and consistent crews."]},
{s:"car-detailing",n:"Car Detailing",c:2,cost:"$2,000–$12,000",season:"Spring and summer, plus pre-winter protection.",fit:"Good for car lovers. Mobile setups keep costs low, but you must build proof through photos.",spend:"Polisher, vacuum, chemicals and towels, water tank or access, insurance.",tips:["Check local rules on water runoff and mobile washing.","Free at irs.gov.","Take deposits online to cut no-shows.","Garage-keepers insurance covers customer cars in your care.","Price in packages (basic, full, premium) by vehicle size.","Post before and after photos and ask for reviews. Fleet and dealer deals are valuable.","If they say “I can wash it myself,” show what paint correction and sealant do."]}
];
var OBJ=[["Roofing","“Your price is higher than the other guy’s.”","“That’s fair, and I’d compare too. What’s included in the other quote? Materials, warranty and cleanup are where prices differ, and I’d rather you choose on what you get.”"],["HVAC","“I need to talk to my spouse first.”","“Of course. What do you think they’ll want to know? I’ll write a one-page summary so you have it all in one place, and I’ll check back Thursday.”"],["House cleaning","“I can find someone cheaper.”","“You probably can. Most clients stay with us for reliability: same crew, on time, same result. Would a one-time deep clean be a good way to see the difference?”"]];
var LEGAL={
privacy:["Privacy policy","<p>Last updated: [date]. This site is run by [Your Name / Company], [address], [country]. Contact: "+CONTACT+".</p><h3>What I collect</h3><p>Only what you send me, such as your email address when you request a playbook. This site has no accounts and no tracking or advertising cookies.</p><h3>Your browser storage</h3><p>Your checklist progress is saved in your own browser (local storage) so it is there when you return. It never leaves your device.</p><h3>Third parties</h3><p>Fonts load from Google Fonts, which may receive your IP address. When you request a playbook, your email address goes through this site’s server and its email delivery service (Brevo) to me.</p><h3>How I use it</h3><p>To send the playbook you asked for and occasional related tips. Every email includes an unsubscribe option, and I never sell your data. Legal basis (EU/UK): your consent, which you can withdraw anytime.</p><h3>Your rights</h3><p>You can ask to see, correct or delete your data, or object to its use, by emailing me. California and other US state residents have similar rights. I keep data only as long as needed.</p><h3>Children</h3><p>This site is for adults and is not directed at children under 16.</p><h3>Changes</h3><p>I may update this policy and will change the date above.</p>"],
terms:["Terms of use","<p>By using this site you agree to these terms.</p><h3>Information only</h3><p>Content is general education. It is provided “as is” without warranties of any kind.</p><h3>Intellectual property</h3><p>The text, design and playbooks belong to [Your Name / Company]. You may use them for your own business but not resell or republish them.</p><h3>Limitation of liability</h3><p>To the fullest extent allowed by law, I am not liable for losses arising from your use of this site or reliance on its content.</p><h3>Links</h3><p>I am not responsible for third-party sites linked from here.</p><h3>Governing law</h3><p>These terms are governed by the laws of [country/state]. I may update them at any time.</p>"],
disclaimer:["Disclaimer","<h3>Not professional advice</h3><p>Nothing here is legal, tax, financial, insurance or licensing advice. Laws and requirements vary by state and city, so check with your state agency and a qualified professional before acting.</p><h3>Cost and income figures</h3><p>Start-up costs and seasons are rough estimates and vary by location and scale. I make no promise of income or results.</p><h3>No affiliation</h3><p>This site is independent and is not affiliated with any government agency, insurer or company mentioned.</p><h3>Communications</h3><p>I send emails only to people who ask for them, and you can opt out at any time.</p>"]};
var L=function(a){return "<ul>"+a.map(function(x){return "<li>"+x+"</li>"}).join("")+"</ul>"};
var Q=function(a){return a.map(function(x){return "<details><summary>"+x[0]+"</summary><p>"+x[1]+"</p></details>"}).join("")};
var S=function(t,c){return "<details><summary>"+t+"</summary>"+c+"</details>"};
var TP=function(x){return "<div class='tpl'>"+x+"</div>"};
LEGAL.about=["About","<p style='font-size:1.2rem;color:var(--ink)'>Hi, I’m [Your Name]. I help new service businesses turn quote requests into booked jobs.</p><h3>Why I built this</h3><p>Most tradespeople are great at the work and were never taught to sell. They lose jobs in the gap between sending a quote and hearing yes. I built this site to give new owners a clear path to starting the business and the words to win customers.</p><h3>My background</h3><p>[X years] in sales, working in [industries / roles]. [One sentence on a result or lesson you’re proud of.] Add a photo and a short personal line here.</p><h3>How I work</h3><p>Everything is remote and written first, so it fits around jobs. I’m based in Europe and work with US businesses. Calls are scheduled for your mornings or after your workday.</p><h3>What I won’t do</h3><p>I won’t promise income, push you into a trade that doesn’t suit you, or give legal or tax advice. I’ll tell you honestly what I think will work.</p><h3>Work with me</h3><p>Start with a free playbook for your trade, or tell me where you lose jobs and I’ll tell you how I’d fix it.</p><div class='cta'><a class='btn' href='#home-contact'>Get the free playbook</a><a class='btn ghost' href='mailto:"+CONTACT+"'>Email me</a></div>"];
LEGAL.sales=["Sales hub","<p>Simple, honest sales scripts for service businesses. Use them as a starting point and put them in your own words. Trade-specific objections are inside each start-up guide (the roofing guide has eight).</p><h3>Four habits behind every script</h3>"+L(["Listen first. Ask what’s going on before you talk price.","Be honest about what you can and can’t do.","Always agree on the next step before the conversation ends.","Follow up. Most quotes go quiet, not “no.”"])+"<h3>The scripts</h3>"+S("1. Answering the first call or message","<p>Goal: sound calm, understand the job, and book a next step. Ask what’s wrong, when they need it done, and for a photo or the address.</p>"+TP("“Thanks for calling [Business], this is [Name]. Tell me what’s going on and I’ll see how we can help.”")+TP("“Can you send me a photo? I can come by Tuesday at 10 or Wednesday at 2. Which works better?”")+"<p>Offer two times, not “whenever works.” It makes booking easier.</p>")+S("2. Presenting a quote","<p>Present by phone or in person when you can, not only by text. Start with their problem, then your solution, then the price, then the next step.</p>"+L(["Offer two or three options (good, better, best) when it fits.","Put scope, price and warranty in writing.","State how long the quote is valid."])+TP("“Here’s what I found, here’s how I’d fix it, and here’s the price. If you’d like to go ahead, I can start Thursday. What questions do you have?”"))+S("3. Following up on quotes","<p>Follow up within 48 hours, again at 5 days, and once more at 10–14 days. Keep each message short, friendly and useful.</p>"+TP("Day 2: “Hi [Name], I wanted to make sure the quote came through. Happy to answer any questions.”")+TP("Day 5: “Hi [Name], checking in on the [job]. I have a spot on [day] if you’d like to get it done.”")+TP("Day 12: “Hi [Name], I’ll close out your quote on Friday so I can free up the schedule. If you’d still like to go ahead, just reply and I’ll hold a spot.”"))+S("4. Closing","<p>Ask directly. Many owners never do. Give a choice between two next steps, not “yes or no.”</p>"+TP("“Would you like to start Monday or Wednesday?”")+"<p>After you ask, stop talking. Silence is okay. If they hesitate, ask what’s holding them back.</p>")+S("5. Handling objections (a simple method)","<p>Acknowledge it, ask a question, answer honestly, then suggest a next step.</p>"+TP("Customer: “That’s more than I expected.” You: “I understand. What number were you hoping for? Let me show you what’s included and where we can adjust.”"))+S("6. Asking for reviews and referrals","<p>Ask right after the job, when they’re happiest. Text a direct review link.</p>"+TP("“Thanks again, [Name]. If you’re happy with the work, would you leave a quick Google review? Here’s the link. And if you know anyone who needs help, I’d appreciate the introduction.”"))+S("7. Handling a “no”","<p>Stay polite and leave the door open. Many people come back.</p>"+TP("“No problem, [Name]. Thanks for considering us. If anything changes, I’m here. Would it be okay if I checked in next month?”"))+"<p style='margin-top:18px'>Want these written for your trade? <a href='#home-contact'>Get the free playbook</a>.</p>"];
var FULL={roofing:{lic:["Rules vary a lot by state. Some states (Florida, Arizona and California, for example) require a state contractor license for roofing. Others (Texas, for example) have no state roofing license, but cities or counties may require registration or permits. Confirm with your state licensing board.","Where a license is required, expect to show experience, pass an exam, and carry insurance and sometimes a bond. This can take weeks or months, so start early.","Many jobs need a local building permit. Some areas also have rules for storm-damage work and door-to-door sales (solicitation permits, cooling-off periods). Check before you knock.","Many states restrict how roofers deal with insurance claims. Never offer to waive a customer’s deductible, because that is illegal in many states.","OSHA fall-protection rules apply once you have employees. Plan for harnesses and training from day one."],cost:[["Business setup (LLC, license, bond)","$300–$2,500"],["General liability insurance","$1,500–$5,000 per year"],["Workers’ compensation","Depends on payroll and state; often the biggest cost once you hire"],["Ladders, safety gear, fall protection","$1,500–$4,000"],["Tools (nailers, compressor, cutters)","$1,500–$4,000"],["Used truck and trailer","$5,000–$20,000 if you don’t already own one"],["Software, website, marketing","$500–$2,500"],["Working capital for materials until customers pay","$3,000–$10,000"]],costnote:"Bare minimum (you own a truck, work solo or with one helper, small repairs) is roughly $8,000–$12,000. A crew-ready start is closer to $25,000–$40,000. These are estimates, so get real quotes.",plan:[["Weeks 1–2","Register the LLC, get your EIN, open the bank account, get insurance quotes and confirm licensing."],["Weeks 3–4","Set up a Google Business Profile, a simple one-page site and a quote template. Open a supplier account. Photograph every job, even small repairs for friends."],["Month 2","Do 5–10 small repairs for neighbors, friends and landlords. Ask each customer for a review and a referral. Introduce yourself to 10 local realtors and property managers."],["Month 3","Start quoting full replacements. Follow up on every quote within 48 hours and again at 5 days. Check which lead sources paid off and do more of those."]],price:"Roofers price replacements by the square (100 sq ft of roof). Example: a 2,400 sq ft roof with moderate pitch is about 28 squares including waste. If materials and labor cost you about $330 per square, that’s $9,240, plus about $600 for dump fees and permits. Add 25–35% for overhead and profit and the quote lands around $12,300–$13,300. Itemize tear-off, underlayment, shingles, flashing, cleanup and warranty. Your own costs will differ, so treat this as an example.",mistakes:["Underinsuring. One fall or leak claim can end a business with no cover.","Spending one customer’s deposit on another job. Pay for each job’s materials first.","Leaving scope and warranty out of the contract.","Underpricing to win jobs, then losing money on rotted decking. Add a clause for hidden damage priced per sheet.","Chasing storm work without checking local solicitation and insurance-claim rules.","Letting quotes go cold. Many sales happen on the second or third contact."],obj:[["“Your price is higher than the other guy’s.”","“That’s fair, I’d compare too. What’s included in the other quote? Materials, underlayment, warranty and cleanup are where prices differ. I’d rather you choose on what you get than on the number alone.”"],["“I need to get a few more quotes.”","“Totally reasonable. To make it easy, compare the materials brand, underlayment, flashing, warranty and who does the work. I’ll check back Thursday to answer any questions.”"],["“I need to talk to my spouse.”","“Of course, it’s a big decision. What do you think they’ll want to know? I’ll send a one-page summary with photos so you can go through it together.”"],["“Can you do it cheaper?”","“I can adjust the materials or scope to hit a budget. What number are you hoping for? Then I’ll show you what that gets. I won’t cut corners on the parts that keep your roof dry.”"],["“My insurance should pay for it.”","“If it’s storm damage, I can document the roof with photos for your adjuster. I can’t waive your deductible, because that’s against the rules in many states, but I’ll make sure the damage is well documented.”"],["“I’ll wait until next year.”","“Understood. Small leaks can turn into rotted decking, which costs a lot more. Want me to patch the leak now so you have time to plan the replacement?”"],["“How do I know you’ll be around for the warranty?”","“Fair question. Here’s my license and insurance, and local references you can call. I put the warranty in writing so you’re covered either way.”"],["“Why do you need a deposit?”","“The deposit pays for your materials so they’re ordered on time. It’s all in the contract, and the balance is due once the work is finished and you’ve approved it.”"]],faq:[["Can I start with just repairs?","Yes. Repairs build reviews, cash and skill with less risk. Move to full replacements once your estimates are solid and your insurance fits."],["Do I need workers’ comp if I work alone?","It varies by state. Even where it isn’t required for a sole owner, many customers and suppliers ask for it, and it is usually required once you have employees. Check your state."],["How do I get paid?","A common structure is a deposit for materials, a payment when work starts, and the balance on completion. Check your state’s limits on deposits."],["Should I do insurance-claim work?","It can be a big source of jobs, but it has legal rules. Never offer to cover a deductible and don’t act as the homeowner’s adjuster. Learn your state’s rules first."],["How do I compete with big roofers?","Be faster, easier to reach and clearer. Small local roofers win with quick quotes, photos, honest communication and strong reviews."]],tools:["Quoting and invoicing: Jobber, Housecall Pro, or a simple spreadsheet to start.","Measuring: aerial measurement reports (such as EagleView or Hover) or the tools many suppliers offer.","Reviews: a Google Business Profile with a short review link you text after every job.","Scheduling: a shared calendar and a weather app so you can reschedule early."]}};
Object.assign(FULL,{
hvac:{lic:['Most states require an HVAC contractor license, and many require an exam and documented experience. Confirm your state’s path with its licensing board.','Handling refrigerants requires federal EPA Section 608 certification, which you earn by passing an exam.','Installs and replacements usually need permits. Efficiency and refrigerant rules change, so check current requirements.'],cost:[['License, exams and EPA 608','$300–$2,000'],['Insurance (liability; workers’ comp once you hire)','$2,000–$6,000 per year'],['Gauges, vacuum pump, recovery machine, hand tools','$3,000–$8,000'],['Used work van','$8,000–$25,000 if you don’t own one'],['Software, website, marketing','$500–$2,500'],['Parts inventory and working capital','$2,000–$8,000']],costnote:'A service-only start with a vehicle you own is roughly $10,000–$15,000. Installs and a full van setup push it toward $30,000 or more.',plan:[['Weeks 1–4','Confirm licensing, earn EPA 608, form the LLC, get your EIN, bank account and insurance.'],['Month 2','Open a supplier account, set flat-rate prices, create a Google Business Profile and offer tune-ups to friends and neighbors.'],['Month 3','Pitch property managers and realtors, launch a maintenance-plan offer and follow up on every quote within 48 hours.']],price:'Use flat-rate pricing: a service call fee plus fixed prices for common repairs. Example: if parts cost $45, an hour of labor costs you $50 and overhead per job is $40, your cost is $135. At a 30% margin the price is about $190. Your numbers will differ.',mistakes:['Working without a license or EPA certification.','Charging hourly and underpricing small jobs.','Skipping maintenance plans, which create repeat income.','Letting replacement quotes go cold.'],obj:[['“Another company is cheaper.”','“That’s fair. Does their quote include a warranty and licensed techs? I’d rather you choose on what you get than on price alone.”'],['“Can’t you just repair it?”','“Sometimes yes. I’ll show you the repair cost and the replacement cost side by side, and what each means for repairs and energy bills over the next few years.”'],['“I’ll wait until it fully breaks.”','“Many systems fail on the hottest or coldest day, when wait times are longest. Want me to book a tune-up now so you’re not caught out?”'],['“I need to talk to my spouse.”','“Of course. I’ll send a one-page summary with the options so you can go through it together, and I’ll check back Thursday.”']],faq:[['Can I do service work only?','Yes. Service and maintenance need less equipment than installs, and they build repeat customers.'],['Do I need a van?','Eventually. Early on, a reliable vehicle with well-organized tools can work, but customers expect a professional setup as you grow.']],tools:['Scheduling and invoicing: Jobber or Housecall Pro.','Maintenance plans: a simple yearly plan with two tune-ups for repeat income.']},
plumbing:{lic:['Most states license plumbers in tiers (apprentice, journeyman, master). Working alone usually needs a master or contractor license, so confirm your state’s path.','Many jobs, such as water heaters and re-pipes, need permits and inspections.','Gas lines and backflow work often need extra certification.'],cost:[['License, exams, bond','$300–$2,500'],['Insurance','$2,000–$6,000 per year'],['Hand and power tools','$2,000–$6,000'],['Drain machine, camera, press tools','$1,500–$8,000'],['Used work van','$8,000–$25,000 if needed'],['Software, marketing, parts stock','$1,500–$5,000']],costnote:'A service-only start with a vehicle you own is roughly $8,000–$12,000. Camera and press tools raise it toward $25,000.',plan:[['Weeks 1–4','Confirm licensing, form the LLC, get your EIN, bank account and insurance.'],['Month 2','Open a supplier account, set flat prices for common jobs, build a Google Business Profile and set up an emergency number.'],['Month 3','Introduce yourself to landlords and property managers, ask every customer for a review and follow up on quotes.']],price:'Quote flat rates for common jobs. Example: a standard water heater swap with a $650 unit, $150 in fittings and permit, and 3 hours of labor at $60 costs you $980. At a 35% margin the price is about $1,500.',mistakes:['Working outside your license, especially on gas lines.','Underpricing emergencies. After-hours work should cost more.','No written estimate or scope.','Skipping permits, which can leave you liable.'],obj:[['“It’s just a small leak.”','“It might be small now, but hidden leaks can rot cabinets and floors. Let me look, and I’ll tell you honestly what’s needed.”'],['“Another plumber is cheaper.”','“That’s fair. Is the quote licensed and insured, and does it include a warranty? I’d rather you compare what’s included.”'],['“Can you do it cheaper if I buy the part?”','“I can, but I can’t warranty parts I don’t supply. If the part fails, you’d pay for the labor twice. What matters most to you?”'],['“I’ll try fixing it myself first.”','“Totally fine for simple things. If it gets worse, call me. I’d turn the water off first and take a photo so I can help faster.”']],faq:[['Should I take emergency calls?','They pay well but disrupt your life. Many new plumbers start with scheduled work, then add an after-hours rate once they have the capacity.'],['Can I start small?','Only within your license. Many states require a license even for small jobs, so check first.']],tools:['Invoicing and dispatch: Jobber, Housecall Pro or ServiceTitan.','Pricing: a flat-rate price book for your 20 most common jobs.']},
painting:{lic:['Many states require a contractor license for painting above a dollar threshold, while others don’t license painters. Check your state and city.','Homes built before 1978 may contain lead paint. EPA’s RRP rule requires certified renovators and lead-safe practices for most paid work in those homes.','Check local rules on spraying and paint waste disposal.'],cost:[['Entity, license if required','$100–$1,000'],['Insurance','$800–$3,000 per year'],['Sprayer, brushes, rollers, tape','$1,000–$4,000'],['Ladders, scaffolding, drop cloths','$500–$2,500'],['Vehicle (if needed)','$0–$12,000'],['Marketing, software','$300–$1,500']],costnote:'Starting small with your own vehicle can cost $2,000–$5,000. A sprayer and crew setup costs more.',plan:[['Weeks 1–4','Check licensing, form the LLC, get your EIN, bank account and insurance.'],['Month 2','Paint a few rooms for friends and family at a fair price, photograph every job and set up a Google Business Profile.'],['Month 3','Ask for reviews and referrals, contact realtors and landlords for turnover work, and follow up on every quote.']],price:'Example: a 12×14 room with 8-foot walls has about 400 sq ft of wall. If paint and supplies cost $80, 8 hours of labor cost you $200 and overhead is $60, your cost is $340. At a 40% margin the price is about $570. Add for prep, repairs and ceilings.',mistakes:['Skipping prep, which causes peeling and callbacks.','Not checking for lead paint in older homes.','Underquoting without counting prep and repairs.','No written scope covering coats, colors and areas.'],obj:[['“My nephew paints cheaper.”','“I’m sure. The difference is prep, insurance and a warranty. If something goes wrong, I come back and fix it. Would you like me to show you what’s included?”'],['“Why does one room cost so much?”','“Most of the work is prep: patching, sanding, taping and two coats. I can show you how the price breaks down.”'],['“Do I really need two coats?”','“For a color change or a clean finish, yes. I can quote one coat for a quick refresh if that suits your budget better.”'],['“I need to think about it.”','“Of course. I’ll hold your date for a few days. What questions can I answer to help you decide?”']],faq:[['Is painting good for beginners?','Yes, the start-up cost is low, but competition is high. Good prep and photos help you stand out.'],['Should I sell by the hour or by the job?','By the job. Customers want a clear price, and you keep the upside when you work efficiently.']],tools:['Estimating: a square-foot price sheet for interiors and exteriors.','Photos: before and after photos on your Google profile and social pages.']},
handyman:{lic:['Many states cap the size of jobs you can do without a contractor license, often at a few thousand dollars. Know your limit.','Electrical, plumbing and gas work often needs a separate license, even for small jobs.','Some cities require a business license or permits for certain repairs.'],cost:[['Entity and business license','$100–$800'],['General liability insurance','$500–$2,500 per year'],['Hand and power tools','$1,000–$4,000'],['Vehicle (if needed)','$0–$10,000'],['Software, website, marketing','$300–$1,500'],['Materials float','$500–$2,000']],costnote:'With tools and a vehicle you already own, you can start for about $1,500–$3,000.',plan:[['Weeks 1–4','Learn your state’s job-size limit, form the LLC, get your EIN, bank account and insurance.'],['Month 2','List a menu of services with prices, join local groups and Nextdoor, and take small jobs.'],['Month 3','Ask every customer for a review and referral, and offer small maintenance packages to landlords.']],price:'Example: if your target is $65 per hour with a 2-hour minimum, your smallest job is $130. For repeat tasks such as mounting a TV or assembling furniture, quote flat prices so customers know the cost upfront.',mistakes:['Working past your license limit.','Taking jobs outside your skills, such as electrical.','Charging too little for small jobs, which don’t cover travel.','Not having insurance, even for small repairs.'],obj:[['“That’s a lot for a small job.”','“I understand. My minimum covers travel, tools and insurance, and I’ll fix a few things in the same visit if you have a list.”'],['“My neighbor charges less.”','“That’s fair. I carry insurance and stand behind my work, which protects you if something goes wrong.”'],['“Can you give me a rough idea over the phone?”','“Happy to give a range. For an exact price I’d like a photo or a quick visit so I don’t surprise you later.”'],['“I’ll do it myself.”','“Good for simple jobs. If you get stuck, I’m here, and I can take the ones you’d rather not do.”']],faq:[['Which jobs should I avoid?','Anything that needs a license you don’t hold, such as major electrical, plumbing or structural work.'],['How do I find customers?','Start with neighbors, local Facebook groups, Nextdoor and a Google Business Profile, then ask for referrals.']],tools:['Booking and invoicing: Jobber, Square or a simple invoicing app.','A written service menu with clear prices.']},
landscaping:{lic:['Plain mowing usually needs no license, but pesticide and herbicide application typically needs a state applicator license.','Irrigation, hardscape and tree work may need a contractor license depending on your state and job size.','Check local rules on leaf-blower noise, trailer weight and yard-waste disposal.'],cost:[['Entity, business license','$100–$800'],['Insurance (liability plus equipment)','$800–$3,000 per year'],['Mower, trimmer, blower, hand tools','$2,500–$8,000'],['Trailer and truck','$3,000–$20,000 if needed'],['Fuel, maintenance, supplies','$500–$1,500'],['Marketing and software','$300–$1,500']],costnote:'A basic mowing start with a vehicle you own can be $3,000–$6,000. Commercial equipment raises it a lot.',plan:[['Weeks 1–4','Check licensing, form the LLC, get your EIN, bank account, insurance and equipment.'],['Month 2','Pick two or three neighborhoods, door-hang flyers on one street and sign your first recurring clients.'],['Month 3','Fill your routes so clients are close together, ask for referrals and add extras like mulching and cleanups.']],price:'Example: an average lawn takes about 45 minutes including drive time. At $60 per hour that’s $45, so set a minimum of $45–$55 per stop and charge more for large or messy lots. Nearby clients raise your hourly earnings.',mistakes:['Driving long distances between clients.','Underpricing overgrown first visits.','No agreement for recurring service, so clients drop out in slow weeks.','Not insuring equipment against theft.'],obj:[['“My kid mows it for free.”','“That’s great for now. I bring reliability and no missed weeks, and I’m insured. Want a quote you can compare?”'],['“Can I skip weeks to save money?”','“Yes, but in growing season grass grows fast, and longer gaps cost more to cut. I can offer an every-other-week plan.”'],['“Can I pay per visit?”','“Of course. A monthly plan can be easier and I can offer a small discount for it.”'],['“Why did the price go up?”','“Fuel, equipment and labor costs have gone up. I keep increases small and give notice, and I’m happy to walk you through the change.”']],faq:[['Is mowing enough to make a living?','It can be with dense routes and recurring clients. Many owners add cleanups, mulching and snow removal to smooth the year.'],['Do I need a license?','Not for basic mowing in most places. Pesticide application usually needs one.']],tools:['Route planning: Google Maps and a scheduling app.','Billing: recurring card payments through Square, Stripe or Jobber.']},
'junk-removal':{lic:['Many areas require a business license, and some require a waste-hauling permit. Check city and county rules.','You can’t dump anywhere. Use transfer stations, landfills or recycling centers, and keep your receipts.','Hazardous items (paint, chemicals, batteries, electronics, asbestos) often have special disposal rules. Decide what you won’t take.'],cost:[['Entity, business license, permits','$100–$1,000'],['Insurance (liability, commercial auto)','$2,000–$6,000 per year'],['Used truck or trailer','$3,000–$20,000'],['Dollies, straps, gloves, tarps','$300–$1,000'],['Dump fees','Ongoing; budget per job'],['Marketing and software','$300–$1,500']],costnote:'A trailer start with your own truck can be $3,000–$6,000. Buying a dump truck or box truck costs much more.',plan:[['Weeks 1–4','Check permits, form the LLC, get your EIN, bank account and insurance, and find your nearest dump sites and fees.'],['Month 2','Set truck-volume prices, build a Google Business Profile and take your first jobs from friends and local groups.'],['Month 3','Pitch realtors, property managers and movers for clean-outs, and ask for reviews.']],price:'Example: a half-truck load costs you $75 in dump fees, $25 in fuel and truck wear, and 2 hours of labor at $50 for $100, so $200 in all. At a 40% margin charge about $335, and add for stairs, heavy items and special disposal.',mistakes:['Not tracking dump fees per job.','Taking hazardous items without proper disposal.','Quoting without seeing the load.','Underpricing small jobs that cost the same in time and fuel.'],obj:[['“I’ll just rent a dumpster.”','“That works for some jobs. With a dumpster you load it, wait for pickup and handle the permits. We do all of it in one visit. Which fits you better?”'],['“That’s a lot for a few items.”','“I understand. The price covers labor, fuel and dump fees, and a minimum applies. If you have more to go, the next items cost less.”'],['“Can I help carry to lower the price?”','“Sure, if you move things to the curb or garage we can reduce the time and the price.”'],['“Will you take everything?”','“Almost everything. Hazardous items like paint and chemicals need special handling. Tell me what you have and I’ll tell you what we can take.”']],faq:[['How do I price a job?','By how much space it takes in your truck (quarter, half, full), plus extras for stairs, heavy items and disposal.'],['Can I donate or recycle?','Yes, and customers like it. Check which charities accept items and what recycling centers charge.']],tools:['Estimating: ask for photos by text before you quote.','Pricing sheet: a simple chart of truck-load prices.']},
'moving-transportation':{lic:['Local moves are regulated by the state, and some states require a license or registration. Interstate moves need USDOT registration and FMCSA operating authority.','Heavier trucks may require a commercial driver’s license (CDL).','Rules on written estimates and liability coverage options apply and vary by state. Check yours.'],cost:[['Entity, state registration','$100–$1,000'],['Insurance (liability, cargo, commercial auto)','$3,000–$10,000 per year'],['Used box truck','$10,000–$30,000 if needed'],['Dollies, pads, straps, tools','$500–$2,000'],['Helpers or labor','Per job; budget payroll'],['Marketing, software','$500–$2,000']],costnote:'A small local start with a rented or owned truck can be $5,000–$10,000. Buying a truck and insuring a crew raises it a lot.',plan:[['Weeks 1–4','Check state rules, form the LLC, get your EIN, bank account and insurance, and line up reliable helpers.'],['Month 2','Set hourly crew rates and minimums, build a Google Business Profile and take your first jobs from local groups.'],['Month 3','Partner with realtors and apartment managers, ask for reviews and follow up on every quote.']],price:'Example: if two movers and a truck cost you $95 per hour in labor, fuel, truck wear and overhead, then at a 35% margin you charge about $145–$150 per hour. Use a 2–3 hour minimum and charge for travel time.',mistakes:['Underinsuring. Damage claims can be very costly.','Hiring cash helpers without checking employment rules.','Not giving a written estimate.','Underestimating job time on stairs and long carries.'],obj:[['“Another mover quoted less.”','“That’s fair. Is their quote hourly or flat, and what insurance do they carry? I’d rather you compare the whole picture.”'],['“Can you give me a flat price?”','“Yes, after seeing the home or a video walkthrough. A flat price protects you if the move takes longer.”'],['“What if something breaks?”','“We’re insured, and I’ll explain your coverage options in writing before the move.”'],['“Can you do it on short notice at the same price?”','“I’ll do my best. Short-notice and peak days can cost more, but let me check my schedule and see what I can offer.”']],faq:[['Local or long-distance first?','Start local. Interstate moves need federal registration, more insurance and more paperwork.'],['Do I need a CDL?','Only for heavier trucks. Many small box trucks don’t need one, but check the weight rating for your truck.']],tools:['Estimates: video walkthroughs to quote accurately.','Scheduling: a shared calendar for crews and trucks.']},
'house-cleaning':{lic:['Most areas don’t license cleaners, but many cities require a general business license.','If you hire cleaners, check whether they count as employees or contractors under your state’s rules. Misclassifying them is a common problem.','Some customers expect bonding. It’s optional but builds trust.'],cost:[['Entity, business license','$100–$800'],['Insurance (liability, bonding)','$400–$1,500 per year'],['Vacuum, supplies, equipment','$300–$1,500'],['Vehicle (if needed)','$0–$10,000'],['Marketing, booking software','$200–$1,000'],['Working capital','$300–$1,000']],costnote:'You can start for $500–$1,500 with a car and basic supplies. A crew and van raise it to several thousand.',plan:[['Weeks 1–4','Check city rules, form the LLC, get your EIN, bank account, insurance and supplies.'],['Month 2','Set prices by home size, list a clear checklist of what’s included, and offer a first-clean discount to neighbors and friends.'],['Month 3','Turn one-time clients into recurring ones, ask for reviews and referrals, and cluster clients by area.']],price:'Example: if a 1,500 sq ft home takes 3 hours and your target is $50 per hour, a recurring clean is about $150. Charge more for the first deep clean, such as $225–$250, and add for pets, extra bathrooms and extras like inside the oven.',mistakes:['Underpricing the first deep clean.','Taking jobs far from your other clients.','No clear checklist of what’s included.','Misclassifying employees as contractors.'],obj:[['“I can find someone cheaper.”','“You probably can. My clients stay for reliability: same cleaner, on time, same result. Would a one-time deep clean be a good way to see the difference?”'],['“Can you do every other week for the same price?”','“Every-other-week visits take longer because more builds up. I can offer a lower weekly rate or a fair price for every other week.”'],['“I’m not comfortable with strangers in my home.”','“I understand. I’m insured and background-checked, and I’m happy to meet first and share references.”'],['“Do I need to be home?”','“Not at all. Many clients leave a key or code, and I send a message when I arrive and when I’m done.”']],faq:[['Is house cleaning a good first business?','Yes. It has a low start-up cost and recurring income, but earning trust and getting consistent clients takes time.'],['Should I hire help?','Once you have more clients than you can handle, but check your state’s rules on employees and contractors first.']],tools:['Booking and billing: Jobber, Square or Housecall Pro.','Checklist: a written scope for each type of clean.']},
'car-detailing':{lic:['Detailing is generally not licensed, but you’ll likely need a business license.','Mobile washing may be regulated. Many places limit runoff into storm drains, so use water-reclamation mats or work where drainage is allowed.','Store chemicals safely and follow each product’s safety data sheet.'],cost:[['Entity, business license','$100–$800'],['Insurance (liability plus garage keepers)','$800–$3,000 per year'],['Polisher, vacuum, extractor','$800–$3,000'],['Chemicals, towels, pads','$300–$1,000'],['Water tank, generator or shop rent','$300–$5,000'],['Marketing, booking software','$300–$1,500']],costnote:'A mobile start can be $2,000–$5,000. Renting a shop or adding ceramic coatings pushes costs up.',plan:[['Weeks 1–4','Check local rules, form the LLC, get your EIN, bank account, insurance and equipment, and practice on your own and friends’ cars.'],['Month 2','Build three packages (basic, full, premium), photograph every job and set up a Google Business Profile and Instagram.'],['Month 3','Ask for reviews, contact car dealers and fleets for repeat work, and offer maintenance plans.']],price:'Example: a full interior and exterior detail on a sedan takes 4 hours. At $45 per hour plus $25 in supplies your cost is $205. At a 40% margin the price is about $340. SUVs and trucks cost more, and pet hair or stains add extra.',mistakes:['Damaging paint with the wrong product or technique. Practice first.','No before photos, which invites disputes.','Underpricing heavily soiled cars.','No deposit, leading to no-shows.'],obj:[['“I can wash it myself.”','“You can, and many people do. Detailing handles what a wash can’t, like paint correction, sealant and deep interior cleaning. Want to see before and after photos?”'],['“Is it worth it for an older car?”','“Often the biggest difference. Tired paint and interiors come back a lot, and a clean car sells for more.”'],['“That seems like a lot for a wash.”','“A detail isn’t a wash. It’s about 4 hours of work with proper products. I can also offer a basic package that fits a smaller budget.”'],['“Will it scratch my paint?”','“Not when it’s done right. I use clean microfiber and the right products, and I’m insured.”']],faq:[['Mobile or shop?','Start mobile. It costs less, and you can move to a shop when demand and revenue justify the rent.'],['Should I offer ceramic coatings?','Later. Coatings pay well but need training, a controlled space and more liability, so master detailing first.']],tools:['Booking and deposits: Square, Jobber or Calendly with online payments.','Photos: a consistent before and after photo routine for your portfolio.']}
});
function extra(t){var f=FULL[t.s];if(!f)return "";return "<div class='legal'><h2 style='margin-top:44px'>"+t.n+" deep dive</h2><h3>Licensing and rules</h3>"+L(f.lic)+"<h3>Itemized start-up costs</h3><div class='xs'><table class='cost'>"+f.cost.map(function(r){return "<tr><td>"+r[0]+"</td><td>"+r[1]+"</td></tr>"}).join("")+"</table></div><p>"+f.costnote+"</p><h3>Your first 90 days</h3>"+f.plan.map(function(r){return "<p><b style='color:var(--ink)'>"+r[0]+":</b> "+r[1]+"</p>"}).join("")+"<h3>Pricing example</h3><p>"+f.price+"</p><h3>Mistakes to avoid</h3>"+L(f.mistakes)+"<h3>Objection library</h3>"+Q(f.obj)+"<h3>Questions people ask</h3>"+Q(f.faq)+"<h3>Tools to consider</h3>"+L(f.tools)+"</div>"}
var app=document.getElementById("app"),done=[];
function get(s){try{return JSON.parse(localStorage.getItem("ft:"+s)||"[]")}catch(e){return[]}}
function put(s,v){try{localStorage.setItem("ft:"+s,JSON.stringify(v))}catch(e){}}
function find(s){return T.filter(function(t){return t.s===s})[0]}
function signup(label){return '<div class="signup" id="signup"><h2>Get the free '+label+' playbook</h2><p>Scripts, tips and objection answers for your trade. Enter your email and I’ll send it to you.</p><form id="f"><input type="email" id="em" required placeholder="you@example.com" aria-label="Your email"><button class="btn" type="submit">Send me the playbook</button></form><label><input type="checkbox" id="ok" form="f" required> I agree to receive the playbook and tips by email, and have read the <a href="#privacy">privacy policy</a>.</label><p id="fs" role="status"></p></div>'}
function wireSignup(label){var f=document.getElementById("f");if(!f)return;f.onsubmit=function(e){e.preventDefault();var b=f.querySelector("button"),ok=document.getElementById("ok"),st=document.getElementById("fs");b.disabled=true;st.textContent="Sending…";fetch(FORM_URL,{method:"POST",headers:{"Content-Type":"application/json",Accept:"application/json"},body:JSON.stringify({email:document.getElementById("em").value,guide:label,consent:ok.checked})}).then(function(r){if(!r.ok)throw r;f.style.display=ok.parentNode.style.display="none";st.textContent="Thanks! I’ll email your "+label+" playbook to you shortly."}).catch(function(){b.disabled=false;st.innerHTML="Sorry, that didn’t go through. Please try again, or email me at <a href='mailto:"+CONTACT+"'>"+CONTACT+"</a>."})}}
function tiles(list){return '<div class="grid">'+list.map(function(t){return '<a class="tile" href="#'+t.s+'"><b>'+t.n+'</b></a>'}).join("")+'</div>'}
function home(){
var h='<section class="hero"><div><h1>Start the business. Then get the jobs.</h1><p class="lead">Free step-by-step start-up guides for service trades, plus sales scripts and objection answers, so you can turn quote requests into booked work.</p><div class="cta"><a class="btn" href="#guides">Browse start-up guides</a><a class="btn ghost" href="#demo">See a sample objection</a></div></div><div class="thread" aria-label="Example text thread: a quote goes quiet, then a follow-up books the job"><div class="msg them">Hi, can you quote a roof repair? Leak over the garage.</div><div class="msg me">Sure. Total is $1,850, parts and labor.</div><div class="gap">6 days of silence</div><div class="msg me late" style="--i:0">Hi Mark, quick check-in. Is the garage leak still dripping? I have a Thursday slot if you want it fixed before the next rain.</div><div class="msg them late" style="--i:1">Yes! Thursday works. Sorry, got busy.</div></div></section>';
h+='<section><h2>What you’ll find here</h2><div class="cols"><div class="col"><h3>Start-up guides</h3><p>Costs, busy season and a checklist from LLC to first customers for ten trades.</p></div><div class="col"><h3>Objection handling</h3><p>Honest answers to “too expensive” and “I need to think about it.”</p></div><div class="col"><h3>Quote follow-up</h3><p>Most quotes go quiet, not “no.” Get messages that bring them back.</p></div></div></section>';
h+='<section id="demo"><h2>A sample objection handler</h2><p>Pick a trade.</p><div class="demo"><div class="tabs" id="tabs"></div><div class="card" aria-live="polite"><div class="q" id="q"></div><p class="a" id="a"></p></div></div></section>';
h+='<section><h2>Start-up guides by trade</h2>'+CATS.map(function(c,i){return '<div class="cat"><h3>'+c+'</h3>'+tiles(T.filter(function(t){return t.c===i}))+'</div>'}).join("")+'</section><div id="home-contact">'+signup("trade")+'</div>';
return h}
function guides(){return '<section><h2>Start-up guides</h2><p>Pick your trade for costs, busy season and a step-by-step checklist.</p>'+CATS.map(function(c,i){return '<div class="cat"><h3>'+c+'</h3>'+tiles(T.filter(function(t){return t.c===i}))+'</div>'}).join("")+'</section>'}
function guide(t){
done=get(t.s);
var h='<section><div class="crumbs"><a href="#guides">Guides</a> / '+CATS[t.c]+'</div><h1>How to start a '+t.n+' business</h1><div class="facts"><div class="fact"><h3>Start-up cost</h3><p>'+t.cost+'</p></div><div class="fact"><h3>Busy season</h3><p>'+t.season+'</p></div><div class="fact"><h3>Is it a good fit?</h3><p>'+t.fit+'</p></div><div class="fact"><h3>Where the money goes</h3><p>'+t.spend+'</p></div></div><p style="font-size:.9rem;color:var(--muted)">Costs are rough estimates. Rules vary by state. See the <a href="#disclaimer">disclaimer</a>.</p><h2>Step by step</h2><div class="prog" id="prog"></div><div class="bar"><i id="bar"></i></div><div style="height:16px"></div>';
STEPS.forEach(function(s,i){h+='<div class="step" id="st'+i+'"><button class="chk" data-i="'+i+'" aria-label="Mark step '+(i+1)+' completed"></button><div><h3>Step '+(i+1)+': '+s[0]+'</h3><p style="margin-bottom:0">'+s[1]+'</p><p class="tip"><b>'+(i===6?'Tips and tricks: ':'What to look for: ')+'</b>'+t.tips[i]+'</p></div></div>'});
h+=extra(t)+'</section>'+signup(t.n)+'<section><h2>Related guides</h2><div class="rel">'+T.filter(function(x){return x.c===t.c&&x.s!==t.s}).map(function(x){return '<a class="btn ghost" target="_blank" rel="noopener" href="'+PUBLIC+'#'+x.s+'">'+x.n+' guide</a>'}).join("")+'<a class="btn ghost" target="_blank" rel="noopener" href="'+PUBLIC+'#guides">All guides</a></div></section>';
return h}
function paint(t){STEPS.forEach(function(s,i){var e=document.getElementById("st"+i),on=done.indexOf(i)>-1;e.className="step"+(on?" done":"");e.firstChild.textContent=on?"✓":"";e.firstChild.setAttribute("aria-pressed",on)});document.getElementById("prog").textContent=done.length+" of 7 steps completed";document.getElementById("bar").style.width=(done.length/7*100)+"%"}
function render(id){
var t=find(id),h;
if(LEGAL[id])h='<section class="legal"><h1>'+LEGAL[id][0]+'</h1>'+LEGAL[id][1]+'</section>';
else if(id==="guides")h=guides();else if(t)h=guide(t);else{h=home();id="home"}
app.innerHTML=h;
if(t){paint(t);app.querySelectorAll(".chk").forEach(function(b){b.onclick=function(){var i=+b.dataset.i,k=done.indexOf(i);k>-1?done.splice(k,1):done.push(i);put(t.s,done);paint(t)}});wireSignup(t.n)}
else if(id==="home"){wireSignup("trade");var tb=document.getElementById("tabs");var sh=function(i){[].forEach.call(tb.children,function(b,k){b.setAttribute("aria-selected",k===i)});document.getElementById("q").textContent=OBJ[i][1];document.getElementById("a").textContent=OBJ[i][2]};OBJ.forEach(function(o,i){var b=document.createElement("button");b.type="button";b.textContent=o[0];b.onclick=function(){sh(i)};tb.appendChild(b)});sh(0)}
document.title=(t?t.n+" start-up guide":LEGAL[id]?LEGAL[id][0]:"FollowThrough")+" | FollowThrough"}
function go(h){var id=(h||"").replace("#","")||"home";if(id==="home-contact"){render("home");var s=document.getElementById("signup");if(s)s.scrollIntoView();return}render(id);window.scrollTo(0,0)}
document.addEventListener("click",function(e){var a=e.target.closest&&e.target.closest('a[href^="#"]');if(a&&!a.target){e.preventDefault();try{history.replaceState(null,"",a.getAttribute("href"))}catch(x){}go(a.getAttribute("href"))}});
window.addEventListener("hashchange",function(){go(location.hash)});
go(location.hash);
</script>
</body>
</html>
